def check_sliding_window_rate_limit(timestamps: list[float], current_time: float, limit: int, window_seconds: float) -> tuple[bool, list[float]]:
    """Evaluates sliding window log rate limiter, evicts expired timestamps, and appends current_time if allowed."""
    if limit <= 0 or window_seconds <= 0:
        raise ValueError("Limit and window_seconds must be positive.")
    cutoff = current_time - window_seconds
    valid_ts = [t for t in timestamps if t > cutoff]
    if len(valid_ts) < limit:
        valid_ts.append(current_time)
        return (True, valid_ts)
    return (False, valid_ts)
